/**
 * Controlled dry-run traces for lesson examples.
 *
 * These are NOT produced by running arbitrary code: each trace is generated by a small TypeScript
 * function that mirrors one fixed C++ snippet. A test compiles every snippet with the real compiler
 * and checks the final output matches the trace, so the visualizer can't drift from C++ semantics.
 */

export type TracePhase = "declare" | "init" | "check" | "body" | "update" | "after" | "call" | "return";

export interface TraceStep {
  /** 1-based line in `code` to highlight. */
  line: number;
  phase: TracePhase;
  vars: Record<string, number>;
  /** Everything printed so far. */
  output: string;
  note: string;
  condition?: { text: string; value: boolean };
  /** Pending function calls, outermost first (recursion traces only). */
  stack?: string[];
}

export interface TraceDef {
  id: string;
  title: string;
  code: string;
  steps: TraceStep[];
}

function sumTrace(): TraceDef {
  const code = `int sum = 0;
for (int i = 1; i <= 5; i++) {
    sum += i;
}
cout << sum;`;
  const steps: TraceStep[] = [];
  let sum = 0;
  let out = "";
  steps.push({ line: 1, phase: "declare", vars: { sum }, output: out, note: "sum is created and starts at 0 — before the loop." });
  let i = 1;
  steps.push({ line: 2, phase: "init", vars: { sum, i }, output: out, note: "Initialization runs once: i starts at 1." });
  for (;;) {
    const ok = i <= 5;
    steps.push({
      line: 2, phase: "check", vars: { sum, i }, output: out, condition: { text: `${i} <= 5`, value: ok },
      note: ok ? `Check: ${i} <= 5 is true, so the body runs.` : `Check: ${i} <= 5 is false, so the loop ends.`,
    });
    if (!ok) break;
    const before = sum;
    sum += i;
    steps.push({ line: 3, phase: "body", vars: { sum, i }, output: out, note: `Body: sum = ${before} + ${i} = ${sum}.` });
    i++;
    steps.push({ line: 2, phase: "update", vars: { sum, i }, output: out, note: `Update: i++ makes i ${i}.` });
  }
  out += String(sum);
  steps.push({ line: 5, phase: "after", vars: { sum }, output: out, note: `After the loop, sum is printed: ${sum}. (i only existed inside the loop.)` });
  return { id: "sum-1-to-5", title: "Adding 1 to 5", code, steps };
}

function countDownTrace(): TraceDef {
  const code = `for (int i = 3; i >= 1; i--) {
    cout << i << " ";
}
cout << "Go!";`;
  const steps: TraceStep[] = [];
  let out = "";
  let i = 3;
  steps.push({ line: 1, phase: "init", vars: { i }, output: out, note: "i starts at 3." });
  for (;;) {
    const ok = i >= 1;
    steps.push({
      line: 1, phase: "check", vars: { i }, output: out, condition: { text: `${i} >= 1`, value: ok },
      note: ok ? `Check: ${i} >= 1 is true — keep going.` : `Check: ${i} >= 1 is false — the loop ends.`,
    });
    if (!ok) break;
    out += `${i} `;
    steps.push({ line: 2, phase: "body", vars: { i }, output: out, note: `Body prints ${i} and a space.` });
    i--;
    steps.push({ line: 1, phase: "update", vars: { i }, output: out, note: `Update: i-- makes i ${i}.` });
  }
  out += "Go!";
  steps.push({ line: 4, phase: "after", vars: {}, output: out, note: "The loop is over, so the next line runs." });
  return { id: "count-down", title: "Counting down", code, steps };
}

function nestedTrace(): TraceDef {
  const code = `for (int row = 1; row <= 2; row++) {
    for (int col = 1; col <= 3; col++) {
        cout << "*";
    }
    cout << "\\n";
}`;
  const steps: TraceStep[] = [];
  let out = "";
  let row = 1;
  steps.push({ line: 1, phase: "init", vars: { row }, output: out, note: "Outer loop: row starts at 1." });
  for (;;) {
    const okRow = row <= 2;
    steps.push({ line: 1, phase: "check", vars: { row }, output: out, condition: { text: `${row} <= 2`, value: okRow }, note: okRow ? `Outer check ${row} <= 2 is true.` : `Outer check ${row} <= 2 is false — all done.` });
    if (!okRow) break;
    let col = 1;
    steps.push({ line: 2, phase: "init", vars: { row, col }, output: out, note: "Inner loop starts over: col = 1." });
    for (;;) {
      const okCol = col <= 3;
      steps.push({ line: 2, phase: "check", vars: { row, col }, output: out, condition: { text: `${col} <= 3`, value: okCol }, note: okCol ? `Inner check ${col} <= 3 is true.` : `Inner check ${col} <= 3 is false — inner loop ends.` });
      if (!okCol) break;
      out += "*";
      steps.push({ line: 3, phase: "body", vars: { row, col }, output: out, note: `Print a star (row ${row}, col ${col}).` });
      col++;
      steps.push({ line: 2, phase: "update", vars: { row, col }, output: out, note: `col++ → ${col}.` });
    }
    out += "\n";
    steps.push({ line: 5, phase: "body", vars: { row }, output: out, note: "End the row with a new line." });
    row++;
    steps.push({ line: 1, phase: "update", vars: { row }, output: out, note: `row++ → ${row}.` });
  }
  return { id: "nested-2x3", title: "A loop inside a loop", code, steps };
}

function factorialTrace(): TraceDef {
  const code = `int factorial(int n) {
    if (n <= 1) return 1;
    return n * factorial(n - 1);
}

int main() {
    cout << factorial(3);
}`;
  const steps: TraceStep[] = [];
  const stack: string[] = ["main()"];
  const snap = () => [...stack];
  steps.push({ line: 7, phase: "call", vars: {}, output: "", stack: snap(), note: "main calls factorial(3) and waits for the answer." });
  const fact = (n: number): number => {
    stack.push(`factorial(${n})`);
    steps.push({ line: 1, phase: "call", vars: { n }, output: "", stack: snap(), note: `A new call starts with its own n = ${n}.` });
    const base = n <= 1;
    steps.push({
      line: 2, phase: "check", vars: { n }, output: "", stack: snap(), condition: { text: `${n} <= 1`, value: base },
      note: base ? "Base case reached: no more calls." : `Not the base case, so factorial(${n}) needs factorial(${n - 1}) first.`,
    });
    let result: number;
    if (base) {
      result = 1;
    } else {
      steps.push({ line: 3, phase: "call", vars: { n }, output: "", stack: snap(), note: `factorial(${n}) pauses at "n * factorial(${n - 1})" and calls factorial(${n - 1}).` });
      const sub = fact(n - 1);
      result = n * sub;
      steps.push({ line: 3, phase: "body", vars: { n }, output: "", stack: snap(), note: `Back in factorial(${n}): ${n} * ${sub} = ${result}.` });
    }
    stack.pop();
    steps.push({ line: base ? 2 : 3, phase: "return", vars: { n }, output: "", stack: snap(), note: `factorial(${n}) returns ${result} and is removed from the stack.` });
    return result;
  };
  const answer = fact(3);
  steps.push({ line: 7, phase: "after", vars: {}, output: String(answer), stack: snap(), note: `main receives ${answer} and prints it.` });
  return { id: "factorial-3", title: "factorial(3) on the call stack", code, steps };
}

export const TRACES: TraceDef[] = [sumTrace(), countDownTrace(), nestedTrace(), factorialTrace()];

export function getTrace(id: string): TraceDef | undefined {
  return TRACES.find((t) => t.id === id);
}
